import { z } from 'zod';

/**
 * Schemas for the map data files (section 4), generated by the map import
 * (`npm run import:map`, see packages/tools/map-config/). Only the fixed map
 * facts live here; starting values such as population come with F71.
 */
const id = z
  .string()
  .regex(/^[a-z0-9]+(_[a-z0-9]+)*$/, 'ids are lowercase letters, digits and single underscores');
const countryId = z
  .string()
  .regex(/^[A-Z]{3}$/, 'country ids are three capital letters (ISO 3166-1 alpha-3)');
/** [longitude, latitude] in degrees. */
const lonLat = z.tuple([z.number().min(-180).max(180), z.number().min(-90).max(90)]);

export const CLIMATES = [
  'tropical',
  'arid',
  'temperate',
  'continental',
  'polar',
  'highland',
] as const;
export type Climate = (typeof CLIMATES)[number];
export const SEA_DEPTHS = ['shallow', 'deep'] as const;
export type SeaDepth = (typeof SEA_DEPTHS)[number];
/** Coast zones run along the shores; open-sea zones lie beyond them (designer decision, F70). */
export const SEA_ZONE_KINDS = ['coast', 'sea'] as const;

/** `data/countries.json` */
export const countriesFileSchema = z.strictObject({
  countries: z.array(
    z.strictObject({
      id: countryId,
      /** The province holding the capital at the start of the campaign. */
      capitalProvince: id,
      /** Political map color [DEFAULT]. */
      mapColor: z.string().regex(/^#[0-9a-f]{6}$/),
    }),
  ),
});

/** `data/provinces.json` */
export const provincesFileSchema = z.strictObject({
  provinces: z.array(
    z.strictObject({
      id,
      /** Owner at the start of the campaign. */
      country: countryId,
      region: id,
      /** Label point inside the province. */
      center: lonLat,
      areaKm2: z.number().min(0),
      adjacentProvinces: z.array(id),
      adjacentSeaZones: z.array(id),
    }),
  ),
});

/** `data/regions.json` */
export const regionsFileSchema = z.strictObject({
  regions: z.array(
    z.strictObject({
      id,
      climate: z.enum(CLIMATES),
      center: lonLat,
      /** Color in the regions map mode [DEFAULT]: chosen by the map import so neighbors are easy to tell apart. */
      mapColor: z.string().regex(/^#[0-9a-f]{6}$/),
    }),
  ),
});

/** `data/sea_zones.json` */
export const seaZonesFileSchema = z.strictObject({
  seaZones: z.array(
    z.strictObject({
      id,
      depth: z.enum(SEA_DEPTHS),
      /** A coast zone (the water along a shore) or an open-sea zone. */
      kind: z.enum(SEA_ZONE_KINDS),
      center: lonLat,
      adjacentSeaZones: z.array(id),
    }),
  ),
});

export type CountriesFile = z.infer<typeof countriesFileSchema>;
export type ProvincesFile = z.infer<typeof provincesFileSchema>;
export type RegionsFile = z.infer<typeof regionsFileSchema>;
export type SeaZonesFile = z.infer<typeof seaZonesFileSchema>;
export type CountryData = CountriesFile['countries'][number];
export type ProvinceData = ProvincesFile['provinces'][number];
export type RegionData = RegionsFile['regions'][number];
export type SeaZoneData = SeaZonesFile['seaZones'][number];

/** Translation keys for map names (the names themselves are in locales/en.map.json). */
export const countryNameKey = (countryIdValue: string) => `COUNTRY_${countryIdValue.toUpperCase()}`;
export const provinceNameKey = (provinceId: string) => `PROVINCE_${provinceId.toUpperCase()}`;
export const regionNameKey = (regionId: string) => `REGION_${regionId.toUpperCase()}`;
export const seaZoneNameKey = (seaZoneId: string) => `SEA_ZONE_${seaZoneId.toUpperCase()}`;
